import{_ as t,o as l,c as r,a2 as p}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"CDS Hammer (Day 1) - Import/Export // Local Import","description":"","frontmatter":{"title":"CDS Hammer (Day 1) - Import/Export // Local Import","date":"2014-10-29T00:00:00.000Z","updated":"2014-10-30T00:00:00.000Z","tags":["Ceph","Rados","导出/导入","分片","指纹验证"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_Hammer_Day_1_-_Import_Export_Local_Import.md","filePath":"posts/2014/CDS_Hammer_Day_1_-_Import_Export_Local_Import.md","lastUpdated":1780459816000}'),a={name:"posts/2014/CDS_Hammer_Day_1_-_Import_Export_Local_Import.md"};function i(s,o,_,n,e,m){return l(),r("div",null,[...o[0]||(o[0]=[p("<p>会议纪要</p><p><strong>会议主题</strong>： Rados 导出/导入功能改进</p><p><strong>会议时间</strong>： 未知</p><p><strong>参会人员</strong>： Danny, Mike, John, Tara 等</p><p><strong>会议内容</strong>：</p><p><strong>一、Rados 导出/导入功能现状</strong></p><ol><li>Rados 导出功能存在性能瓶颈，数据量大时导出速度慢，且在不同文件系统上导出失败率较高。</li><li>导入功能也存在问题，将数据重新导入新集群的速度较慢。</li></ol><p><strong>二、改进方案</strong></p><ol><li><p><strong>导出功能</strong>：</p><ul><li>采用类似 RBD 导出和 RBD 差分的流式导出，提高灵活性。</li><li>支持快照导出，导出特定快照状态的数据。</li><li>支持分片导出，并行导出数据。</li><li>添加指纹验证功能，确保导出的数据完整性。</li></ul></li><li><p><strong>导入功能</strong>：</p><ul><li>改进导入性能，提高数据导入速度。</li><li>支持从快照中恢复数据。</li><li>支持分片导入，并行导入数据。</li></ul></li><li><p><strong>其他</strong>：</p><ul><li>支持复制池功能，将池状态导出并复制到另一个池。</li><li>添加 RBD 命令支持导入差分到本地文件，方便创建新镜像。</li></ul></li></ol><p><strong>三、行动计划</strong></p><ol><li>Danny 负责改进导出/导入功能代码。</li><li>Mike 负责设计指纹验证功能。</li><li>John 和 Tara 负责测试改进后的功能。</li></ol><p><strong>四、后续讨论</strong></p><ol><li>讨论了快照导出的具体实现方式。</li><li>讨论了分片导出/导入的实现细节。</li><li>讨论了指纹验证功能的实现方案。</li></ol><p><strong>五、会议总结</strong></p><p>本次会议讨论了 Rados 导出/导入功能的改进方案，并制定了相应的行动计划。改进后的功能将提高 Rados 的数据迁移和备份能力，并确保数据完整性。</p>",15)])])}const c=t(a,[["render",i]]);export{d as __pageData,c as default};
